/* ROSA Leagues: role-aware views; competition rules and authorization live on the server. */
(() => {
  'use strict';
  const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let state=null,leagueId=localStorage.getItem('rosa-league'),role='organizer',roundId='',groupId='',search='',authMode='login',wizard=null,step=0,shared=null,shareFilter='',busy=false,lastFocus=null;
  const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M3 5h18v16H3zM16 3v4M8 3v4M3 11h18M7 15h3M14 15h3',trophy:'M8 3h8v6a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 13v6M8 21h8',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',share:'M12 16V3M7 8l5-5 5 5M5 12v9h14v-9',settings:'M4 7h16M4 17h16M9 4v6M15 14v6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',court:'M3 4h18v16H3zM12 4v16M3 8h18M3 16h18',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5'};
  const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
  const brand=(light=false)=>`<div class="brand ${light?'light':''}"><img src="assets/rosa-${light?'light':'dark'}.svg" width="120" height="35" alt="ROSA"><small>LEAGUES</small></div>`;
  const button=(label,action,cls='',attrs='',symbol='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${symbol?icon(symbol):''}${label}</button>`;
  const pill=(s,label=s)=>`<span class="pill ${esc(s)}">${esc(label)}</span>`;
  const l=()=>state?.leagues.find(l=>l.id===leagueId),round=()=>l()?.rounds.find(r=>r.id===roundId)||l()?.rounds.at(-1),entry=id=>l()?.entrants.find(e=>e.id===id);
  const playerName=id=>{for(const e of l()?.entrants||[]){const p=e.players.find(p=>p.id===id);if(p)return p.name;}for(const r of l()?.rounds||[])for(const a of Object.values(r.attendance))if(a.substitute?.id===id)return `${a.substitute.name} (sub)`;return 'Player';};
  const fmt=(at,opts={})=>at?new Date(at).toLocaleString('en-GB',{timeZone:l()?.rules.timezone||shared?.league.rules.timezone||'UTC',weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',...opts}):'Time to be arranged';
  const signed=n=>n>0?`+${n}`:String(n);
  const heading=(title,sub,actions='')=>`<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="row">${actions}</div></div>`;
  const empty=(title,sub,action='')=>`<div class="panel empty">${icon('court')}<h2>${esc(title)}</h2><p>${esc(sub)}</p>${action}</div>`;
  const field=(label,name,value='',type='text',extra='',help='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${help?`<small>${help}</small>`:''}</div>`;
  const select=(label,name,choices,value,extra='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${choices.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
  const check=(label,name,on)=>`<label class="check"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;
  const mine=m=>m.sides.some(s=>s.some(p=>state.user.playerIds.includes(p)));
  async function api(path,body){const res=await fetch(path,{credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok){const error=new Error(data.error||'Request failed.');error.status=res.status;throw error;}return data;}
  function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
  function modal(title,sub,content){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${button('','close','ghost square','aria-label="Close dialog"','close')}</div>${sub?`<p class="dialog-desc">${esc(sub)}</p>`:''}${content}<p id="form-error" class="error" role="alert"></p>`;if(!$('#modal').open)$('#modal').showModal();}
  function close(){ $('#modal').close();lastFocus?.focus(); }
  async function refresh(renderIt=true){state=await api('/api/state');if(!l())leagueId=state.leagues[0]?.id;localStorage.setItem('rosa-league',leagueId||'');if(l()&&!l().organizer)role='player';if(renderIt)render();}
  async function action(type,data={},extra={}){if(busy)return;busy=true;try{const result=await api('/api/action',{type,data,leagueId,revision:l()?.revision,...extra});if(result.leagueId){leagueId=result.leagueId;roundId='';role='organizer';location.hash='#overview';}await refresh(false);return result;}finally{busy=false;}}
  function auth(){ $('#app').innerHTML=`<div class="auth"><section class="auth-story">${brand()}<div><div class="eyebrow">From first serve to next week</div><h1>The league moves.<br>Everyone stays<br>in the game.</h1><p>Groups, court times, results and the next round. Connected through ROSA, with a clear place for every player.</p></div><div class="steps"><div><span>01</span>Play your group. Rotate partners or opponents.</div><div><span>02</span>ROSA records. Players confirm fallback results.</div><div><span>03</span>Standings update. The next round is ready.</div></div></section><section class="auth-form"><div><div class="eyebrow muted">ROSA league workspace</div><h2>${authMode==='login'?'Welcome back.':'Join your league.'}</h2><p class="muted small">${authMode==='login'?'Sign in to your organizer or player account.':'Create your player account, then open your invitation or registration link.'}</p><form id="auth-form">${authMode==='register'?field('Your name','name','','text','required autocomplete="name"'):''}${field('Email address','email','','email','required autocomplete="username"')}${field('Password','password','','password',`required ${authMode==='register'?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'}`)}${button(authMode==='login'?'Sign in':'Create account','submitAuth','primary','type="submit"','arrow')}<p id="auth-error" class="error" role="alert"></p></form><button class="text-btn" data-action="toggleAuth">${authMode==='login'?'New player? Create an account':'Already registered? Sign in'}</button><div class="notice">${location.hash.includes('invite/')?'Your player invitation will be linked after sign-in.':'Organizer credentials are configured by the server administrator. Demo leagues are available inside the organizer workspace.'}</div></div></section></div>`; }
  function render(){
    if(!state){auth();return;}if(!location.hash||location.hash==='#hub'){hub();return;}if(location.hash.startsWith('#share/'))return;if(location.hash.startsWith('#group/')){const bits=location.hash.split('/');leagueId=bits[1];roundId=bits[2];const r=round(),g=r?.groups.find(g=>g.id===bits[3]);if(g){groupPage(r,g);return;}}
    const league=l(),view=location.hash.slice(1)||'overview';
    const nav=[['overview','grid','Overview'],['rounds','calendar','Groups & fixtures'],['roster','users','Players'],['standings','trophy','Standings'],['insights','bolt','Round insights'],['sharing','share','Share center'],['settings','settings','League settings']];
    let content=!league?empty('Your next league starts here','Set up the competition once. ROSA takes care of the recurring work.',state.user.admin?`${button('Create a league','create','primary','','plus')} ${button('Explore individual demo','demo','','data-format="individual"')} ${button('Explore fixed-pair demo','demo','','data-format="pairs"')}`:'Open the invitation or registration link from your organizer.'):role==='player'&&view==='overview'?playerView():({overview:overview,rounds:advancedRounds,roster:managerRoster,standings:standings,insights:insights,sharing:sharing,settings:settings}[view]||overview)();
    $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="navlabel">League workspace</div><nav class="nav" aria-label="League navigation">${nav.filter(n=>n[0]!=='settings'||league?.organizer).map(([path,i,label])=>`<a href="#${path}" class="${view===path?'active':''}" ${view===path?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-foot"><p>Every round, connected.</p><small>ROSA Leagues · Pilot</small></div></aside><div class="workspace"><header class="topbar"><div><select id="league-select" aria-label="Select league">${state.leagues.map(x=>`<option value="${x.id}" ${x.id===leagueId?'selected':''}>${esc(x.name)}${x.demo?' · Demo':''}</option>`).join('')}${state.user.admin?'<option value="new">+ Create a league</option>':''}</select><small>${esc(league?.club||'Your league workspace')}</small></div><div class="row"><span class="small muted sync"><i class="dot"></i>Connected</span>${league?.organizer?`<div class="role">${button('Organizer','role','','data-role="organizer"')}${button('Player view','role','','data-role="player"')}</div>`:''}<span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span>${state.user.id?button('Sign out','logout','ghost small'):'<a class="btn small" href="#login">Sign in</a>'}<a class="btn small ghost" href="#hub">Hub</a></div></header><main id="content">${content}<footer class="footer"><span>${league?.demo?'Demo league · simulated ROSA results':'ROSA Leagues · local / hosted pilot'} · ${esc(league?.rules.timezone||'')}</span><span>Groups. Games. Community.</span></footer></main></div></div>`;
    document.querySelectorAll('[data-action="role"]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));
    document.querySelectorAll('.progress span[data-progress]').forEach(el=>el.style.width=`${el.dataset.progress}%`);
  }
  function overview(){const x=l(),r=x.rounds.at(-1),n=r?.matches.length||0,done=r?.matches.filter(m=>m.status==='official').length||0,pending=r?.matches.filter(m=>['pending','disputed'].includes(m.status)).length||0;
    return heading('League overview',`${x.rules.format==='individual'?'Individual · rotating partners':'Fixed pairs · rotating opponents'} · ${x.rules.rounds} matchdays`,x.organizer?button(x.status==='registration'?'Register players':'Share this round',x.status==='registration'?'add':'shareRound','primary','','plus'):'')+`<section class="hero"><div><div class="eyebrow">${x.status==='registration'?'Registration is open':x.status==='complete'?'Season complete':`Round ${r.number} of ${x.rules.rounds}`}</div><h2>${x.status==='registration'?'Build the league. Let it run.':x.status==='complete'?'A season worth sharing.':'Your next round takes care of itself.'}</h2><p>${x.status==='registration'?'Add players or import your roster, check the session windows, then publish the first round.':`${done} of ${n} results official. ${pending?`${pending} awaiting confirmation or review.`:'ROSA and organizer scores publish directly; player scores need one opponent.'} The next round opens automatically when all results are confirmed.`}</p></div><div class="stack">${x.status==='registration'&&x.organizer?button('Publish first round','start','primary','','arrow'):x.demo&&x.organizer&&x.status==='active'?`${button('Simulate next result','demoNext','primary','','bolt')}${button('Complete demo round','demoRound','ghost')}`:`<div class="hero-number">${done}<span class="small"> / ${n}</span></div>`}</div></section><div class="stats">${[['Registered players',x.entrants.reduce((a,e)=>a+e.players.length,0),`${x.entrants.length} league entries`,'users'],['Groups this round',r?.groups.length||Math.floor(x.entrants.length/4),'Level is separate from ranking','court'],['Official results',done,`${n-done} still to come`,'check'],['Rounds completed',x.rounds.filter(r=>r.status==='complete').length,`${x.rules.rounds} in this season`,'trophy']].map(([label,v,note,i])=>`<div class="stat"><div class="stat-label">${label}${icon(i)}</div><div class="value">${v}</div><small>${note}</small></div>`).join('')}</div>${r?`<div class="dashboard"><div><div class="section-head"><h2>This week’s groups</h2><a href="#rounds" class="text-btn">All fixtures →</a></div><div class="group-grid">${r.groups.map(g=>groupCard(g,r)).join('')}</div></div><aside><section class="panel"><div class="panel-head"><h2>League activity</h2></div><div class="activity">${(x.audit||[]).slice(0,5).map(a=>`<div class="activity-item"><p>${esc(a.text)}</p><span class="muted">${fmt(a.at,{weekday:undefined,day:undefined,month:undefined})}</span></div>`).join('')||'<p class="padded small muted">Confirmed results appear in your fixtures.</p>'}</div></section><div class="automation">${icon('bolt')}<h3>Automatic progression</h3><p>Official scores → points → standings → promotion and relegation → next round. Disputed results stay open for review.</p></div></aside></div>`:empty('Four entries make a group','Register players, set their initial seed order, and review court capacity before publishing.',button('Manage players','goRoster'))}`;
  }
  function groupCard(g,r){const ms=r.matches.filter(m=>m.groupId===g.id),done=ms.filter(m=>m.status==='official').length,first=[...ms].filter(m=>m.scheduledAt).sort((a,b)=>a.scheduledAt.localeCompare(b.scheduledAt))[0];return `<article class="group-card"><div class="group-title"><h3>Group ${g.level}</h3>${pill(done===ms.length?'complete':'scheduled',`${done}/${ms.length} official`)}</div><div class="group-meta">${icon('clock')}${first?esc(fmt(first.scheduledAt)):'Arrange by '+esc(fmt(r.deadline))}</div>${g.entrants.map((eid,i)=>`<div class="entry-row"><span class="position">${i+1}</span><strong>${esc(entry(eid)?.name)}</strong><span class="pts">${signed(l().ranking.find(e=>e.id===eid)?.total||0)} pts</span></div>`).join('')}<div class="group-bottom"><small>${g.schedulingIssue?'Needs court time':esc([...new Set(ms.map(m=>m.court).filter(Boolean))].join(' · ')||'Flexible booking')}</small>${button('Fixtures','group','ghost small',`data-id="${g.id}"`)}</div><div class="progress"><span data-progress="${done/ms.length*100}"></span></div></article>`;}
  function roundTools(){return `<div class="toolbar"><select id="round-select" aria-label="Matchday">${l().rounds.map(r=>`<option value="${r.id}" ${r.id===round()?.id?'selected':''}>Round ${r.number} · ${r.status}</option>`).join('')}</select><select id="group-select" aria-label="Filter by group"><option value="">All groups</option>${round()?.groups.map(g=>`<option value="${g.id}" ${groupId===g.id?'selected':''}>Group ${g.level}</option>`).join('')}</select><span class="small muted">${esc(l().rules.timezone)}</span></div>`;}
  function matchCard(m,r){const g=r.groups.find(g=>g.id===m.groupId),can=l().organizer||mine(m);return `<article class="match-card"><div class="match-top"><span>Group ${g.level} · Rotation ${m.stage}</span>${pill(m.status,m.status==='pending'?'Awaiting opponent':m.status)}</div>${m.sides.map((side,i)=>`<div class="side"><strong>${esc(side.map(playerName).join(' / '))}</strong><span class="score">${m.score?.[i]??m.submission?.score?.[i]??'–'}</span></div>`).join('')}<div class="match-footer"><div><p>${esc(fmt(m.scheduledAt))} · ${esc(m.court||'Court to be agreed')}</p>${m.source?`<p>Source: ${esc(m.source)}</p>`:''}${m.proposal?`<p>Proposed: ${esc(fmt(m.proposal.at))} · ${esc(m.proposal.court)}</p>`:''}${m.dispute?`<p class="negative">${esc(m.dispute.reason)}</p>`:''}</div><div class="row wrap">${m.status!=='official'&&can?button(m.status==='pending'?'Review score':'Enter score','score',m.status==='pending'?'primary small':'small',`data-id="${m.id}"`):''}${m.status==='scheduled'&&can?button(m.proposal?'Review time':'Arrange time','schedule','ghost small',`data-id="${m.id}"`):''}${l().organizer?button('QR','matchShare','ghost small',`data-id="${m.id}" aria-label="Share match QR"`):''}</div></div></article>`;}
  function roundsView(){const r=round();return heading('Groups & fixtures','Every rotation, court and result in one place.',l().organizer&&r?button('Share round','shareRound','primary','','share'):'')+(!r?empty('No round published yet','The first round is generated from your seeded roster.'):roundTools()+`${r.groups.some(g=>g.schedulingIssue)?'<div class="notice warn"><strong>Some groups need more court time</strong>Use Arrange time on unscheduled fixtures, or expand the recurring sessions for future rounds.</div>':''}<div class="match-list">${r.matches.filter(m=>(!groupId||m.groupId===groupId)&&(role!=='player'||!state.user.playerIds.length||mine(m))).map(m=>matchCard(m,r)).join('')}</div>`);}
  function roster(){const x=l(),r=x.rounds.at(-1);return heading('Players & registration','Seed once. Track attendance and replacements by round.',x.organizer?`${button('Import CSV','import','','','download')}${button('Add entry','add','primary','','plus')}`:'')+`${x.requests?.length?`<section class="panel padded"><h3>Registration requests</h3>${x.requests.map(req=>`<div class="review-row"><strong>${esc(req.names.join(' / '))}</strong>${button('Approve','approve','small',`data-id="${req.id}"`)}</div>`).join('')}</section>`:''}<div class="toolbar"><input id="search" aria-label="Search players" placeholder="Search players or pairs…" value="${esc(search)}">${x.organizer?button('Registration link','joinShare','','','share'):''}<span class="small muted">${x.entrants.length} entries · ${x.rules.format==='individual'?'1 player':'2 players'} per entry</span></div><div class="panel table-wrap"><table><thead><tr><th>Seed</th><th>Entry / players</th><th>Attendance this round</th><th>Actions</th></tr></thead><tbody>${[...x.entrants].sort((a,b)=>a.seed-b.seed).filter(e=>e.name.toLowerCase().includes(search.toLowerCase())).map(e=>`<tr data-entry="${e.id}" draggable="${x.organizer&&x.status==='registration'}"><td>${x.organizer&&x.status==='registration'?`<button class="drag-handle" aria-label="Drag ${esc(e.name)} to seed">⠿</button>`:''}${e.seed}</td><td><strong>${esc(e.name)}</strong><small>${e.active===false?'Withdrawn · future rounds':x.rules.format==='individual'?'Individual':'Fixed pair'} · level ${e.rating||'unrated'}</small></td><td>${e.players.map(p=>`${pill(r?.attendance[p.id]?.status||'scheduled',r?.attendance[p.id]?.substitute?'Substitute assigned':r?.attendance[p.id]?.status||'Not started')} `).join('')}</td><td><div class="row wrap">${x.organizer?`${button('Edit','editEntry','ghost small',`data-id="${e.id}"`)}${button(e.active===false?'Restore':'Withdraw','toggleEntry','ghost small',`data-id="${e.id}"`)}${button('Level','setRating','ghost small',`data-id="${e.id}"`)}`:''}${!x.organizer&&e.players.some(p=>state.user.playerIds.includes(p.id))?button('My level','setRating','ghost small',`data-id="${e.id}"`):''}${x.organizer&&x.status==='registration'?`${button('Seed','seed','ghost small',`data-id="${e.id}"`)}${button('Remove','remove','ghost small danger',`data-id="${e.id}"`)}`:''}${e.players.map(p=>`${x.organizer?button(`Account · ${esc(p.name.split(' ')[0])}`,'accountLink','ghost small',`data-id="${p.id}"`):''}${x.organizer?button(`Invite ${esc(p.name.split(' ')[0])}`,'invite','ghost small',`data-id="${p.id}"`):''}${r?.status==='active'&&(x.organizer||state.user.playerIds.includes(p.id))?button(`Attendance${e.players.length>1?' · '+esc(p.name.split(' ')[0]):''}`,'attendance','small',`data-id="${p.id}"`):''}`).join('')}</div></td></tr>`).join('')}</tbody></table></div>${x.status==='registration'?`<div class="notice"><strong>${x.entrants.length%4?`${4-x.entrants.length%4} more entries needed to complete the last group`:'Roster forms complete groups of four'}</strong>Promotion moves players or pairs between groups. Global ranking is calculated separately from accumulated points.</div>`:''}`;}
  function rankingTable(rows){return `<div class="panel table-wrap"><table><thead><tr><th>Rank</th><th>${l()?.rules.format==='pairs'?'Pair':'Player'}</th><th>Group</th>${(rows[0]?.history||[]).map((_,i)=>`<th>J${i+1}</th>`).join('')}<th>Total</th><th>Wins</th><th>Promotions</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${e.rank<=3?'★ ':''}${e.rank}</td><td><strong>${esc(e.name)}</strong></td><td>${e.group}</td>${e.history.map(n=>`<td class="mono ${n>0?'positive':n<0?'negative':''}">${signed(n)}</td>`).join('')}<td class="mono"><strong>${signed(e.total)}</strong></td><td>${e.wins}/${e.played}</td><td>${e.up?`↑ ${e.up}`:'—'}</td></tr>`).join('')}</tbody></table></div>`;}
  function standings(){return heading('Season standings','Accumulated game difference. Ties retain the prior round’s ranking.',l().organizer?button('Share standings','shareRound','primary','','share'):'')+rankingTable(l().ranking)+`<div class="notice">Group level measures where you play; ranking measures accumulated points. Standings only include completed, fully confirmed rounds.</div>`;}
  function facts(cards){return `<div class="fact-grid">${cards.map(f=>`<article class="fact"><div class="eyebrow">Community spotlight</div><h3>${esc(f.title)}</h3><div class="names">${f.names.map(name=>{const e=l()?.entrants.find(e=>e.name===name);return e?`<button class="evidence-name" data-action="evidence" data-id="${e.id}">${esc(name)} ↗</button>`:esc(name);}).join('<br>')}</div><p>${esc(f.detail)}</p></article>`).join('')}</div>`;}
  function insights(){const selected=round()?.status==='complete'?round():l().rounds.filter(r=>r.status==='complete').at(-1);const cards=l().roundInsights?.[selected?.id]||l().insights;return heading('Round insights','Real results, shared achievements. Use these for weekly highlights and side prizes.',l().organizer?button('Share highlights','shareRound','primary','','share'):'')+(`<div class="toolbar"><select id="round-select" aria-label="Insights matchday">${l().rounds.filter(r=>r.status==='complete').map(r=>`<option value="${r.id}" ${r.id===selected?.id?'selected':''}>Through round ${r.number}</option>`).join('')}</select></div>`)+(cards.length?facts(cards):empty('The first stories are still being played','Insights appear after a complete round. Expected attendance is never counted as confirmed attendance.'))+`<div class="notice">Highlights show every tied leader. “Perfect round” means 3 wins from 3 played sets. Guest substitutions are excluded from the absent entrant’s playing statistics.</div>`;}
  function playerView(){const x=l(),r=x.rounds.at(-1),owned=x.entrants.find(e=>e.players.some(p=>state.user.playerIds.includes(p.id))),preview=!owned&&x.organizer,t=owned||(preview?x.entrants[0]:null),related=r?.matches.filter(m=>m.entrySides.flat().includes(t?.id))||[],next=related.find(m=>m.status!=='official'),g=r?.groups.find(g=>g.entrants.includes(t?.id));return `<div class="player-hero"><div class="eyebrow muted">${esc(x.name)} ${preview?'· Organizer preview':''}</div><h1>${t?'Your next league night.':'Welcome to the league.'}</h1><p>${t?esc(t.name):'Your registration is awaiting approval.'}${preview?' · Preview only. Use a player account to confirm results.':''}</p></div>${t?`<div class="player-layout"><section class="player-next"><div class="eyebrow">${next?'Up next':'Your round'}</div><h2>${next?.court?esc(next.court):g?`Group ${g.level}`:'Registration complete'}</h2><p>${next?esc(fmt(next.scheduledAt)):'Your next fixtures will appear here.'}</p>${next?next.sides.map(side=>`<div class="side"><strong>${esc(side.map(playerName).join(' / '))}</strong></div>`).join(''):''}<div class="review-row"><span>Deadline</span><strong>${r?esc(fmt(r.deadline)):'Not published'}</strong></div>${next?button('Open my fixtures','goRounds','primary','','arrow'):''}</section><section class="panel padded"><h2>Your matchday</h2><p class="small muted">${r?`Round ${r.number} · ${esc(r.rules.timezone)}`:'Waiting for the first round'}</p>${related.map(m=>`<div class="review-row"><span>Rotation ${m.stage}</span><strong>${m.status==='official'?m.score.join('–'):esc(fmt(m.scheduledAt))}<br>${pill(m.status)}</strong></div>`).join('')}${owned&&r?.status==='active'?owned.players.filter(p=>state.user.playerIds.includes(p.id)).map(p=>button('Check in / declare absence','attendance','ghost',`data-id="${p.id}"`)).join(''):''}</section></div>`:''}<div class="notice">Keep your match page open for score updates. QR fallback scores need one opponent’s confirmation. Times are shown in the league’s time zone.</div>`;}
  function settings(){const x=l(),s=x.rules;return heading('League settings','Set the rules once. Give each club the flexibility it needs.',`${button('This round','roundConfig')}${button('Next round only','nextConfig')}${button('League defaults','editSettings','primary')}`)+`<div class="player-layout"><section class="panel padded"><h2>Competition</h2>${[['Format',s.format==='pairs'?'Fixed pairs':'Rotating partners'],['Season',`${s.rounds} rounds`],['Promotion',s.promotion?'Top up, bottom down':'Disabled'],['Ties','Previous global ranking'],['Absence',s.absencePenalty==='lowestMinus'?`Lowest present score − ${s.penaltyPoints}`:s.absencePenalty==='fixed'?`−${s.penaltyPoints} points`:'No points penalty'],['Announced absence',s.announcedExempt?'Exempt from points penalty':'Standard penalty'],['Substitute score',s.substituteCredit==='original'?'Credit original entry before penalty':'No credit to original entry']].map(([k,v])=>`<div class="review-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><section class="panel padded"><h2>Scheduling</h2>${[['Mode',s.scheduling==='sessions'?'Recurring session windows':'Player-arranged within deadline'],['First round',s.startDate],['Time zone',s.timezone],['Cadence',`Every ${s.intervalDays} days`],['Deadline',`${s.deadlineDays} days after round start`],['Group estimate / rest',`${s.groupMinutes||90} / ${s.restMinutes} minutes`],['Physical courts',s.courts.join(', ')]].map(([k,v])=>`<div class="review-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section></div>${button('Connect ROSA court monitor','pairCourt','','','court')}${(x.connectedCourts||[]).map(c=>`<p class="small">${esc(c.localCourt)} → ${esc(c.name)} · ${esc(c.courtId)}</p>`).join('')}${x.demo?button('Restart demo','resetDemo','ghost danger'):''}${s.scheduling==='sessions'?`<section class="panel padded form-section"><h2>Recurring windows</h2>${s.sessions.map(s=>`<div class="review-row"><span>${esc(s.label)}</span><strong>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][s.day]} ${s.start} · ${s.duration} min · ${s.groups} groups<br>${esc(s.courts.join(', '))}</strong></div>`).join('')}</section>`:''}<div class="notice"><strong>Changes apply to future rounds</strong>Each published round keeps a snapshot of its rules. Reschedule current fixtures from Groups & fixtures. Manage arrivals, withdrawals and next-round groups from Players. The competition format stays fixed.</div>`;}
  function sharing(){return heading('Share center','Weekly groups, standings and achievements—ready for your community.')+`<div class="fact-grid"><section class="fact"><div class="eyebrow">Weekly groups</div><h3>Where everyone plays</h3><p>Group level, player names, physical court, session time and fixtures. Filter by day before exporting.</p>${l().organizer?button('Create round link','shareRound','primary'):'<a href="#rounds" class="btn primary">View public groups</a>'}</section><section class="fact"><div class="eyebrow">Standings & stories</div><h3>The week in numbers</h3><p>Round-by-round points, league standings and community highlights generated from official results.</p>${l().organizer?button('Open sharing page','shareRound'):'<a href="#standings" class="btn">View standings</a>'}</section><section class="fact"><div class="eyebrow">Registration</div><h3>Bring the league together</h3><p>Share a registration link. Approve entries and send each player their personal account invitation.</p>${l().organizer?button('Registration link','joinShare'):'<p class="small">Use the registration link provided by your organizer.</p>'}</section></div><div class="notice">Sharing pages include copyable text, a printable PDF layout and PNG group cards. You choose where to share; the app does not send WhatsApp messages or emails automatically. Links expose names and league results to anyone holding the link.</div>${l().organizer?button('Revoke all league share links','revokeShares','ghost danger'):''}`;}
  function openWizard(edit=false){wizard=edit?{name:l().name,club:l().club,rules:structuredClone(l().rules),edit:true}:{name:'',club:'',rules:structuredClone(state.defaults),edit:false};step=0;drawWizard();}
  function readWizard(){const f=$('#wizard-form');if(!f)return;const d=Object.fromEntries(new FormData(f));if(step===0){wizard.name=d.name;wizard.club=d.club;wizard.rules.format=d.format;wizard.rules.rounds=Number(d.rounds);}if(step===1){const form=new FormData(f);for(const k of ['scheduling','timezone'])wizard.rules[k]=d[k];if(wizard.scope)wizard.roundDate=d.startDate;else wizard.rules.startDate=d.startDate;for(const k of ['intervalDays','deadlineDays','matchMinutes','restMinutes','groupMinutes'])wizard.rules[k]=Number(d[k]);const count=Math.max(1,Math.min(40,Number(d.courtCount)||4));wizard.rules.courts=Array.from({length:count},(_,i)=>wizard.rules.courts[i]||`Court ${i+1}`);if(d.scheduling==='sessions'&&f.querySelector('.session-row'))wizard.rules.sessions=[...f.querySelectorAll('.session-row')].map((el,i)=>({label:d[`s${i}-label`],day:Number(d[`s${i}-day`]),start:d[`s${i}-start`],duration:Number(d[`s${i}-duration`]),groups:d[`s${i}-groups`],courts:form.getAll(`s${i}-courts`).filter(c=>wizard.rules.courts.includes(c))}));}if(step===2){wizard.rules.absencePenalty=d.absencePenalty;wizard.rules.penaltyPoints=Number(d.penaltyPoints);wizard.rules.substituteCredit=d.substituteCredit;wizard.rules.absentMovement=d.absentMovement;wizard.rules.announcedExempt=!!d.announcedExempt;wizard.rules.promotion=!!d.promotion;}}
  function drawWizard(){const r=wizard.rules;let html='';
    if(step===0)html=`<div class="form-grid">${field('League name','name',wizard.name,'text','required minlength="3" placeholder="e.g. Tuesday Club League"')}${field('Club / venue','club',wizard.club,'text','required')}${select('Competition format','format',[['individual','Individual · rotate partners'],['pairs','Fixed pairs · rotate opponents']],r.format,wizard.edit&&l().status!=='registration'?'disabled':'')}${field('Rounds in the season','rounds',r.rounds,'number','required min="1" max="52"')}</div><div class="capacity">${icon('court')}<div><strong>One league model, two ways to play</strong><p>Individuals play 3 partner rotations. Four fixed pairs play a round robin: 6 single-set fixtures, 3 per pair. Points use game difference.</p></div></div>`;
    if(step===1)html=scheduleWizard(r);
    if(step===2)html=`<div class="form-grid">${select('Absence points policy','absencePenalty',[['lowestMinus','Lowest present group score minus penalty'],['fixed','Fixed negative points'],['none','No points penalty']],r.absencePenalty)}${field('Penalty points','penaltyPoints',r.penaltyPoints,'number','required min="0" max="100"')}${select('Substitute game-difference credit','substituteCredit',[['original','Credit original entry before absence penalty'],['none','No game-difference credit to original entry']],r.substituteCredit)}${select('Absent entry movement','absentMovement',[['bottom','Place penalized absences last in the group'],['points','Use points and normal tiebreaker']],r.absentMovement)}<div class="full">${check('Announced absences are exempt from points penalties','announcedExempt',r.announcedExempt)}</div><div class="full">${check('Automatically promote the top entry and relegate the bottom entry','promotion',r.promotion)}</div></div><div class="notice"><strong>Results and progression</strong>ROSA results are official immediately. Organizer entries are official immediately. Player entries require one opponent’s confirmation. The next round publishes automatically. Substitutes are guests; their appearances remain in match history.</div>`;
    if(step===3){const block=r.format==='individual'?(r.groupMinutes||90):6*r.matchMinutes+2*r.restMinutes,slots=r.sessions.reduce((n,w)=>n+Math.floor(w.duration/block)*w.courts.length,0),needed=Math.ceil((l()?.entrants.filter(e=>e.active!==false).length||0)/4);html=`<div class="stack"><h3>${esc(wizard.name)}</h3>${[['Format',r.format==='individual'?'Rotating partners':'Fixed pairs'],['Season',`${r.rounds} rounds · from ${r.startDate}`],['Scheduling',r.scheduling==='sessions'?`${r.sessions.length} recurring windows`:'Player proposals + opponent acceptance'],['Time zone',r.timezone],['Physical courts',r.courts.join(', ')],['Scoring','Game difference; player scores need an opponent. Organizer and ROSA scores are official.'],['Progression','Automatic after every result is official']].map(([a,b])=>`<div class="review-row"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="capacity">${icon('calendar')}<div><strong>${r.scheduling==='sessions'?`Up to ${slots} complete groups before eligibility and shared-court constraints`:`Matches due ${r.deadlineDays} days after round start`}</strong><p>${r.scheduling==='sessions'?`${needed} groups in the current roster. ${slots<needed?'Capacity is short: add a window, extend available hours, or choose flexible scheduling. ':''}Actual allocations respect shared players, rest, odd/even rules and physical court conflicts. Any overflow is flagged in the round.`:'Players propose a time and court; one opponent accepts. Conflicting bookings are rejected.'}</p></div></div>${wizard.edit?`<div class="notice">${wizard.scope==='current'?'Applies to this round. Scored and bound fixtures keep their assignments.':wizard.scope==='next'?'Applies to the next round only. Recurring defaults return afterwards.':'Applies to future rounds. Published rounds keep their existing rules.'}</div>`:''}`;}
    modal(wizard.scope==='current'?'Edit this round':wizard.scope==='next'?'Prepare next round':wizard.edit?'Configure your league':'Create a league','Clear rules now. Less organizing every week.',`<div class="wizard-steps">${['League','Scheduling','Rules','Review'].map((s,i)=>`<span class="${step===i?'active':''}">${i+1}. ${s}</span>`).join('')}</div><form id="wizard-form">${html}<div class="wizard-actions">${button(step?'Back':'Cancel',step?'wizardBack':'close','ghost','type="button"')}${button(step===3?'Save league':'Continue',step===3?'wizardSave':'wizardNext','primary','type="submit"','arrow')}</div></form>`);
  }
  function showMatch(id){const r=l().rounds.find(r=>r.matches.some(m=>m.id===id)),m=r.matches.find(m=>m.id===id),s=m.submission;if(m.status==='official'){modal('Official result',m.score.join('–'),`${m.sides.map(side=>`<p>${esc(side.map(playerName).join(' / '))}</p>`).join('')}${visionSection(m)}${l().organizer&&r.status==='active'?button('Correct result','correctScore','ghost',`data-id="${m.id}"`):''}`);return;}modal('Match result',`Group ${r.groups.find(g=>g.id===m.groupId).level} · rotation ${m.stage}. One complete set, to 6 games with a tiebreak at 6–6.`,`<form id="score-form" data-id="${id}"><div class="score-inputs">${m.sides.map((side,i)=>field(esc(side.map(playerName).join(' / ')),`score${i}`,s?.score[i]??'','number','required min="0" max="7"')).join('')}</div>${s?`<div class="notice">Submitted ${s.score.join('–')}. ${m.status==='disputed'?'Disputed: '+esc(m.dispute.reason):'Review before confirming. Changing a score requires a new submission.'}</div>`:''}<div class="row wrap">${button(s?'Submit correction':'Submit score','submitScore','primary','type="submit"')}${m.status==='pending'&&mine(m)?`${button('Confirm submitted score','confirm','',`type="button" data-id="${id}" data-submission="${s.id}"`)}${button('Dispute','dispute','ghost danger',`type="button" data-id="${id}"`)}`:''}</div></form>${l().organizer&&!l().demo&&m.status==='scheduled'?`<div class="form-section">${m.binding?button('Release court session','unbind','ghost',`data-id="${id}"`):button('Bind ROSA court session','bind','ghost',`data-id="${id}"`)}<p class="small muted">Use a known scoring session and the exact player IDs. Hardware results are authenticated by the server.</p></div>`:''}`);}
  function showSchedule(id){const r=l().rounds.find(r=>r.matches.some(m=>m.id===id)),m=r.matches.find(m=>m.id===id);modal(m.proposal?'Review proposed time':'Arrange this fixture',`Choose a time in ${r.rules.timezone}. The match must finish before ${fmt(r.deadline)}.`,`<form id="schedule-form" data-id="${id}"><div class="form-grid">${field('Date and time in league time zone','localDate','','datetime-local','required')}${select('Physical court','court',r.rules.courts.map(c=>[c,c]),m.court||r.rules.courts[0])}</div><div class="notice">${l().organizer?'Organizer scheduling applies immediately after conflict checks.':'Your opponent must accept the proposal before it becomes the scheduled time.'}</div>${m.proposal?`<div class="notice"><strong>${esc(fmt(m.proposal.at))} · ${esc(m.proposal.court)}</strong>${button('Accept proposed time','acceptSchedule','',`type="button" data-id="${id}" data-proposal="${m.proposal.id}"`)}</div>`:''}${button(l().organizer?'Set time':'Propose time','submitSchedule','primary','type="submit"')}</form>`);}
  function localISO(value,zone){const [date,time]=value.split('T');let at=Date.parse(value+'Z'),target=at;const f=new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});for(let i=0;i<3;i++){const p=Object.fromEntries(f.formatToParts(at).map(p=>[p.type,p.value]));at+=target-Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}Z`);}if(f.format(at).slice(0,16).replace(' ','T')!==`${date}T${time}`)throw new Error('This local time does not exist due to daylight saving.');return new Date(at).toISOString();}
  function linkDialog(url,title='Share league'){modal(title,'This browser-local showcase can copy and open its own view. Signed invitations and scannable QR links activate on the shared VPS backend.',`<div class="link-box">${esc(url)}</div><div class="row wrap">${button('Copy link','copyLink','primary',`data-url="${esc(url)}"`)}<a class="btn" href="${esc(url)}" target="_blank" rel="noopener">Open page ↗</a></div>`);}
  async function showShared(t){shared=await api('/api/share?token='+encodeURIComponent(t));shared.token=t;renderShared();}
  function renderShared(){const s=shared,r=s.round,zone=s.league.rules.timezone,groups=r?.groups.filter(g=>!shareFilter||g.matches.some(m=>m.session===shareFilter))||[],sessions=[...new Set(r?.groups.flatMap(g=>g.matches.map(m=>m.session).filter(Boolean))||[])];$('#app').innerHTML=`<main class="share-page" id="content"><header class="share-head">${brand(true)}<div><h2>${esc(s.league.name)}</h2><p class="small muted">${esc(s.league.club)}</p></div></header><div class="share-title"><div class="eyebrow muted">${s.join?'League registration':`Round ${r?.number||'—'} · ${r?.status||'Registration'}`}</div><h1>${s.join?'Join the next league.':'Your weekly groups.'}</h1><p class="share-scope">${r?`${esc(r.startDate)} · ${esc(zone)} · Results through round ${r.status==='complete'?r.number:r.number-1}`:esc(zone)}</p></div>${s.join?`<div class="panel padded"><h2>${s.league.rules.format==='pairs'?'Register your fixed pair':'Register as an individual'}</h2><p class="muted small">${state?'Your request will go to the organizer for approval.':'Sign in or create a player account, then return to this link.'}</p><form id="join-form">${select('Self-assessed playing level','rating',[[1,'1 · New'],[2,'2 · Beginner'],[3,'3 · Improver'],[4,'4 · Intermediate'],[5,'5 · Advanced'],[6,'6 · Competitive'],[7,'7 · Elite']],3)}${s.league.rules.format==='pairs'?field('Partner name','partner','','text','required'):''}<div class="share-tools">${button(state?'Request registration':'Sign in to register','join','primary','type="submit"')}</div></form></div>`:''}<div class="share-tools no-print"><select id="share-filter" aria-label="Filter sharing by session"><option value="">All sessions</option>${sessions.map(v=>`<option value="${esc(v)}" ${v===shareFilter?'selected':''}>${esc(v)}</option>`).join('')}</select>${button('Copy weekly text','copyWeekly','','','share')}${button('Print / save PDF','print','','','download')}${button('Download group cards','downloadCards','primary','','download')}<a class="btn" href="#overview">${state?'Open my league':'Sign in'}</a></div>${s.matchId?`<div class="notice"><strong>Match QR</strong>Sign in with your player account, then open your fixtures to submit or confirm this result. ${button('Open match','openSharedMatch','small','data-id="'+s.matchId+'"')}</div>`:''}<div class="group-grid">${groups.map(g=>{const first=g.matches.find(m=>m.scheduledAt);return `<article class="group-card"><div class="group-title"><h3>Group ${g.level}</h3>${pill('scheduled',first?.session||'Flexible')}</div><div class="group-meta">${first?esc(fmt(first.scheduledAt)):`Deadline ${esc(fmt(r.deadline))}`}</div>${g.entries.map((e,i)=>`<div class="entry-row"><span class="position">${i+1}</span><strong>${esc(e.name)}</strong><span class="pts">${signed(e.points)} pts</span></div>`).join('')}<div class="group-bottom"><small>${esc([...new Set(g.matches.map(m=>m.court).filter(Boolean))].join(' · ')||'Court to be arranged')}</small></div>${g.matches.map(m=>`<div class="entry-row small"><span class="position">R${m.stage}</span><span>${esc(m.sides.map(s=>s.join(' / ')).join(' vs '))}<br><span class="muted">${esc(fmt(m.scheduledAt))} · ${esc(m.court||'TBC')}${m.score?' · '+m.score.join('–'):''}</span></span></div>`).join('')}</article>`;}).join('')}</div><section class="share-card"><div class="section-head"><h2>League standings</h2><span class="small muted">${esc(s.league.rules.format==='pairs'?'Fixed pairs':'Individuals')}</span></div>${rankingTable(s.ranking)}</section><section class="share-card"><div class="section-head"><h2>Community highlights</h2></div>${facts(s.insights)}</section><footer class="footer"><span>Generated from ROSA league data · ${esc(zone)}</span><span>Shared snapshot view · refresh for updates</span></footer></main>`;}
  function weeklyText(){const s=shared,r=s.round;if(!r)return `${s.league.name}\nRegistration: ${location.href}`;return `${s.league.name} — Round ${r.number}\n${s.league.club} · ${r.rules.timezone}\n\n`+r.groups.filter(g=>!shareFilter||g.matches.some(m=>m.session===shareFilter)).map(g=>`GROUP ${g.level}\n${g.entries.map(e=>e.name).join('\n')}\n${g.matches.map(m=>`Rotation ${m.stage}: ${fmt(m.scheduledAt)} · ${m.court||'Court TBC'} · ${m.sides.map(s=>s.join(' / ')).join(' vs ')}${m.score?' · '+m.score.join('–'):''}`).join('\n')}`).join('\n\n')+`\n\nStandings & updates: ${location.href}`;}
  async function copy(text){await navigator.clipboard.writeText(text);toast('Copied. Ready to paste into WhatsApp or email.');}
  async function downloadCards(){const r=shared.round;if(!r)throw new Error('Publish a round first.');await document.fonts.ready;const logo=new Image();logo.src='/assets/rosa-dark.svg';await logo.decode();for(const g of r.groups.filter(g=>!shareFilter||g.matches.some(m=>m.session===shareFilter))){const c=document.createElement('canvas');c.width=1080;c.height=680+g.matches.length*85;const x=c.getContext('2d');x.fillStyle='#232325';x.fillRect(0,0,c.width,c.height);x.drawImage(logo,64,54,200,58);x.fillStyle='#e2e2e2';x.font='500 20px Pretendard';x.fillText('LEAGUES',66,143);x.font='650 33px Pretendard';wrapText(x,shared.league.name,64,213,950,39);x.fillStyle='#e4007c';x.font='700 57px Pretendard';x.fillText(`ROUND ${r.number}  /  GROUP ${g.level}`,64,305);x.fillStyle='#e2e2e2';x.font='500 30px Pretendard';g.entries.forEach((e,i)=>x.fillText(e.name,64,375+i*48,950));x.strokeStyle='#555';x.beginPath();x.moveTo(64,570);x.lineTo(1016,570);x.stroke();g.matches.forEach((m,i)=>{const y=618+i*85;x.font='600 23px Pretendard';x.fillText(`Rotation ${m.stage} · ${m.court||'Court TBC'}${m.score?' · '+m.score.join('–'):''}`,64,y);x.font='400 20px Pretendard';x.fillText(fmt(m.scheduledAt),64,y+30);});x.font='400 18px Pretendard';x.fillStyle='#b6b6ba';x.fillText(`${shared.league.club} · ${r.rules.timezone} · Full fixtures in the app`,64,c.height-32,950);await new Promise(resolve=>c.toBlob(blob=>{download(blob,`rosa-round-${r.number}-group-${g.level}.png`);resolve();},'image/png'));}toast('Group cards downloaded. Share the weekly link alongside them.');}
  function wrapText(x,text,px,py,max,line){let words=text.split(' '),current='';for(const w of words){if(x.measureText(current+w).width>max){x.fillText(current,px,py);py+=line;current='';}current+=w+' ';}x.fillText(current,px,py);}
  function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
  function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if((c===','||c==='\n')&&!quoted){row.push(cell.trim());cell='';if(c==='\n'){rows.push(row);row=[];}}else if(c!=='\r')cell+=c;}if(quoted)throw new Error('CSV contains an unclosed quote.');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows.filter(r=>r.some(Boolean));}
  function hub(){const active=state.leagues.filter(x=>x.status!=='complete'),past=state.leagues.filter(x=>x.status==='complete');const cards=xs=>xs.map(x=>`<a class="hub-league panel padded" href="#league/${x.id}"><div class="row between">${pill(x.status)}${x.demo?pill('rosa','Demo'):''}</div><h2>${esc(x.name)}</h2><p>${esc(x.club)}</p><div class="small muted">${x.entrants.length} ${x.rules.format==='pairs'?'pairs':'players'} · ${x.rounds.length} rounds · ${esc(x.rules.timezone)}</div><span class="text-btn">Explore league →</span></a>`).join('');$('#app').innerHTML=`<main class="share-page"><header class="share-head">${brand(true)}<div class="row">${state.user.id?button('My workspace','workspace'): '<a href="#login" class="btn primary">Sign in to play</a>'}</div></header><div class="heading"><div><div class="eyebrow muted">The club community</div><h1>Find your league.</h1><p>Groups, results, standings and the stories behind every round. Open to everyone.</p></div>${state.user.admin?button('Create league','create','primary'):''}</div><h2>Active leagues</h2><div class="hub-grid">${cards(active)||'<p class="muted">No active leagues yet.</p>'}</div><h2>Past seasons</h2><div class="hub-grid">${cards(past)||'<p class="muted">Completed seasons will appear here.</p>'}</div>${state.user.admin?`<div class="row wrap">${button('New individual demo','demo','','data-format="individual"')}${button('New fixed-pair demo','demo','','data-format="pairs"')}</div>`:''}</main>`;}
  function groupDirectory(r){return `<section class="panel table-wrap"><table class="directory"><thead><tr><th>Group</th><th>Players / pairs</th><th>Session & court</th><th>Results</th></tr></thead><tbody>${r.groups.map(g=>{const ms=r.matches.filter(m=>m.groupId===g.id),first=ms.find(m=>m.scheduledAt);return `<tr><td><a href="#group/${l().id}/${r.id}/${g.id}" class="text-btn">Group ${g.level}</a></td><td>${g.entrants.map(id=>esc(entry(id)?.name)).join(' · ')}</td><td>${first?esc(fmt(first.scheduledAt)):'Needs scheduling'}<small>${esc([...new Set(ms.map(m=>m.court).filter(Boolean))].join(', '))}</small></td><td>${ms.filter(m=>m.status==='official').length}/${ms.length}</td></tr>`;}).join('')}</tbody></table></section>`;}
  function compactGroup(g,r,open=false){const ms=r.matches.filter(m=>m.groupId===g.id),first=ms.find(m=>m.scheduledAt);return `<details class="group-details panel" ${open?'open':''}><summary><div class="row between"><h3>Group ${g.level}</h3>${pill(ms.every(m=>m.status==='official')?'official':'scheduled',`${ms.filter(m=>m.status==='official').length}/${ms.length} official`)}</div><p>${g.entrants.map(id=>esc(entry(id)?.name)).join(' · ')}</p><small>${first?esc(fmt(first.scheduledAt)):'Needs scheduling'} · ${esc([...new Set(ms.map(m=>m.court).filter(Boolean))].join(' / ')||'No court assigned')}</small></summary><div class="group-actions"><a class="btn primary" href="#group/${l().id}/${r.id}/${g.id}">${ms.every(m=>m.status==='official')?'View group results':'Enter / review group scores'}</a>${l().organizer&&r.status==='active'?button('Reschedule group','groupSchedule','',`data-group="${g.id}"`):''}${l().organizer?button('Group QR','groupQR','',`data-group="${g.id}" data-round="${r.id}"`):''}</div><div class="table-wrap"><table class="fixture-table"><thead><tr><th>Rotation</th><th>Side A</th><th>Side B</th><th>Score</th><th>Court / time</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr><td>${m.stage}</td><td>${esc(m.sides[0].map(playerName).join(' / '))}</td><td>${esc(m.sides[1].map(playerName).join(' / '))}</td><td><strong>${(m.score||m.submission?.score)?.join('–')||'—'}</strong><small>${m.status}</small></td><td>${esc(m.court||'Unassigned')}<small>${esc(fmt(m.estimatedAt||m.scheduledAt))}${m.estimatedAt&&m.estimatedAt!==m.scheduledAt?' · estimated':''}</small></td><td>${l().organizer||mine(m)?button(m.status==='official'?'Review':'Open','score','small',`data-id="${m.id}"`):''}${m.status==='scheduled'&&(l().organizer||mine(m))?button('Time','schedule','ghost small',`data-id="${m.id}"`):''}</td></tr>`).join('')}</tbody></table></div>${g.schedulingIssue?`<div class="notice warn">${esc(g.schedulingIssue)}</div>`:''}</details>`;}
  function advancedRounds(){const r=round();return heading('Groups & fixtures','Find your group, see the whole league, and open just the detail you need.',l().organizer?`${button('Edit this round','roundConfig','','','calendar')}${button('QR pack','qrPack','primary')}`:'')+(!r?empty('No round published','Register your entries, then publish the first round.'):roundTools()+`${r.groups.some(g=>g.schedulingIssue)?`<div class="notice warn"><strong>${r.groups.filter(g=>g.schedulingIssue).length} groups need more court time</strong>The available sessions are full. Edit this round to add a session, extend its hours, or switch to flexible scheduling. You can also reschedule a group directly.</div>`:''}<div class="section-head"><h2>All groups at a glance</h2>${l().organizer?button('Edit group allocation','editGroups','small'):''}</div>${groupDirectory(r)}<div class="section-head"><h2>Group details</h2><span class="small muted">Expand a group to see rotations</span></div><div class="stack">${r.groups.filter(g=>!groupId||g.id===groupId).map(g=>compactGroup(g,r,!!groupId)).join('')}</div>`);}
  function groupPage(r,g){const ms=r.matches.filter(m=>m.groupId===g.id),done=ms.every(m=>m.status==='official'),can=m=>state.user.id&&(l().organizer||mine(m));$('#app').innerHTML=`<main class="share-page"><header class="share-head">${brand(true)}<a href="#league/${l().id}" class="btn">Back to league</a></header>${heading(`${l().name} · Group ${g.level}`,`Round ${r.number} · ${done?'Official results':'Enter and confirm this group’s scores'}`)}<div class="notice"><strong>${g.entrants.map(id=>esc(entry(id)?.name)).join(' · ')}</strong>${done?'All results are registered.':l().organizer?'Organizer scores become official immediately.':'Player scores need one opponent’s confirmation.'}</div>${!state.user.id?`<a href="#login" data-action="groupLogin" class="btn primary">Sign in to enter scores</a>`:''}<form id="group-score-form" data-round="${r.id}"><div class="group-score-grid">${ms.map(m=>`<section class="panel padded"><div class="row between"><h3>Rotation ${m.stage}</h3>${pill(m.status)}</div><p class="small muted">${esc(m.court||'Court not assigned')} · ${esc(fmt(m.estimatedAt||m.scheduledAt))}</p>${m.sides.map((side,i)=>`<div class="group-score-line"><label for="group-${m.id}-${i}">${esc(side.map(playerName).join(' / '))}</label><input id="group-${m.id}-${i}" aria-label="Rotation ${m.stage} side ${i+1} score" name="${m.id}-${i}" type="number" min="0" max="7" value="${m.score?.[i]??m.submission?.score?.[i]??''}" ${m.status==='official'||!can(m)?'disabled':''}></div>`).join('')}${m.status==='pending'&&can(m)?`<div class="row wrap">${button('Confirm opponent score','confirm','small',`type="button" data-id="${m.id}" data-submission="${m.submission.id}"`)}${button('Dispute','dispute','small ghost danger',`type="button" data-id="${m.id}"`)}</div>`:''}${m.status==='official'&&r.status==='active'&&l().organizer?button('Correct result','correctScore','ghost small',`type="button" data-id="${m.id}"`):''}${m.walkover?'<p class="small">Walkover · excluded from played-set highlights</p>':''}${l().organizer&&r.status==='active'&&m.status!=='official'?button('Award walkover','walkover','ghost small',`type="button" data-id="${m.id}"`):''}${visionSection(m)}</section>`).join('')}</div>${!done&&ms.some(can)?button(l().organizer?'Register group scores':'Submit scores for confirmation','saveGroup','primary','type="submit"'):''}<p class="error" id="group-error" role="alert"></p></form><div class="notice">Leave unfinished scores blank. Completed results stay visible here whenever this QR is scanned.</div></main>`;}
  function visionSection(m){return `<section class="vision-section"><h4>ROSA Vision</h4>${m.vision?.links&&Object.keys(m.vision.links).length?`<p class="small muted">Linked ROSA match: ${esc(m.vision.rosaMatchId||'—')}</p><div class="row wrap">${Object.entries(m.vision.links).map(([k,v])=>`<a class="text-btn" href="${esc(v)}" target="_blank" rel="noopener">${esc(({summary:'Round summary',replay:'Replay',livestream:'Livestream',analytics:'Statistics & AI analytics'})[k])} ↗</a>`).join('')}</div>`:'<p class="small muted">No Vision recording linked yet. A connected court can add the summary, statistics, replay, livestream and analytics here.</p>'}${l().organizer?button('Link ROSA match','vision','ghost small',`type="button" data-id="${m.id}"`):''}</section>`;}
  function scheduleWizard(r){return `<div class="form-grid">${select('Scheduling mode','scheduling',[['sessions','Automatic club sessions'],['flexible','Players arrange within a deadline']],r.scheduling)}${field('Time zone','timezone',r.timezone,'text','required')}${field(wizard.scope==='next'?'Next round start date':wizard.scope==='current'?'This round start date':'First round start date','startDate',wizard.roundDate||r.startDate,'date','required')}${field('Days between rounds','intervalDays',r.intervalDays,'number','min="1" max="60" required')}${field('Deadline after start (days)','deadlineDays',r.deadlineDays,'number','min="1" max="59" required')}${field('How many physical courts?','courtCount',r.courts.length,'number','min="1" max="40" required')}${field('Minutes for all 3 rotations','groupMinutes',r.groupMinutes||90,'number','min="30" max="360" required','Initial group estimate; normally 90 minutes.')}${field('Minutes per fixed-pair fixture','matchMinutes',r.matchMinutes,'number','min="5" max="180" required')}${field('Rest between rotations (minutes)','restMinutes',r.restMinutes,'number','min="0" max="60" required')}</div><div class="capacity"><div><strong>${r.courts.length} courts · ${Math.ceil((l()?.entrants.filter(e=>e.active!==false).length||0)/4)} groups</strong><p>At ${r.groupMinutes||90} minutes per individual group, a three-hour window holds two groups per available court. Add another day or a longer window if demand exceeds capacity.</p></div></div>${r.scheduling==='sessions'?`<div class="form-section"><h3>Session windows</h3><p class="small muted">Choose court buttons. Uncheck a damaged or rain-affected court for this window.</p>${r.sessions.map((s,i)=>`<fieldset class="session-row"><legend>Session ${i+1}</legend>${field('Session name',`s${i}-label`,s.label)}${select('Weekday',`s${i}-day`,['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((v,i)=>[i,v]),s.day)}${field('Start time',`s${i}-start`,s.start,'time','required')}${field('Window length (minutes)',`s${i}-duration`,s.duration,'number','min="30" max="720" required')}${select('Eligible groups',`s${i}-groups`,[['all','Any group · automatic allocation'],['odd','Odd-numbered groups'],['even','Even-numbered groups']],s.groups)}<div class="field full"><label>Available courts</label><div class="court-picker">${r.courts.map(c=>`<label><input type="checkbox" name="s${i}-courts" value="${esc(c)}" ${s.courts.includes(c)?'checked':''}><span>${esc(c)}</span></label>`).join('')}</div></div>${button('Remove window','removeSession','ghost small danger',`type="button" data-index="${i}"`)}</fieldset>`).join('')}${button('Add another window','addSession','','type="button"','plus')}</div>`:'<div class="notice"><strong>Flexible round</strong>Players propose a court and time before the deadline. Opponents accept. The organizer can assign or change any unstarted fixture.</div>'}`;}
  function rosterManagerTools(){return `<div class="toolbar">${l().status==='registration'?button('Seed from self-ratings','ratingSeed','','','users'):button('Prepare next-round groups','nextGroups','','','users')}${l().status==='needs-roster'?button('Publish repaired next round','resume','primary'):''}</div>`;}
  function managerRoster(){let html=roster();html=html.replace('<div class="toolbar">',(l().organizer?rosterManagerTools():'')+'<div class="toolbar">');return html;}
  function groupEditor(next=true){const x=l(),r=round(),active=x.entrants.filter(e=>e.active!==false),rows=next?(x.nextGroups||Array.from({length:Math.ceil(active.length/4)},(_,i)=>active.slice(i*4,i*4+4).map(e=>e.id))):r.groups.map(g=>g.entrants);modal(next?'Prepare next round groups':'Edit current groups',next?'Changes apply to the next generated round. Keep four active entries in each group.':'Available before scoring or binding begins. Current fixture IDs and QR codes will be replaced.',`<form id="groups-form" data-scope="${next?'next':'current'}"><div class="stack">${rows.map((ids,i)=>`<fieldset><legend>Group ${i+1}</legend><div class="form-grid">${[0,1,2,3].map(j=>select(`Slot ${j+1}`,`g${i}-${j}`,[['','Choose entry'],...active.map(e=>[e.id,e.name])],ids[j]||'')).join('')}</div></fieldset>`).join('')}</div>${button('Save group allocation','saveGroups','primary','type="submit"')}</form>`);}
  async function showEvidence(id){const e=await api(`/api/evidence?league=${l().id}&entry=${id}&through=${round()?.status==='complete'?round().number:52}`);modal(e.name,'The official results behind this player’s league record.',`<div class="stack">${e.rounds.map(r=>`<details open><summary><strong>Round ${r.number} · ${signed(r.points||0)} points · ${r.wins||0} wins${r.absent?' · absent':''}</strong></summary><p class="small muted">Group ${r.group||'—'} · movement ${r.movement||0}</p>${r.matches.map(m=>`<p class="small">${m.sides.map(s=>esc(s.join(' / '))).join(' vs ')} · <strong>${m.score.join('–')}</strong> · ${esc(m.source)}</p>`).join('')}</details>`).join('')||'<p>No completed-round evidence yet.</p>'}</div>`);}

  document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.type==='submit'&&b.form)return;ev.preventDefault();try{

    if(a==='workspace'){location.hash='#overview';return;}
    if(a==='groupLogin'){sessionStorage.setItem('rosa-login-return',location.hash);location.hash='#login';return;}
    if(a==='roundConfig'||a==='nextConfig'){openWizard(true);wizard.scope=a==='roundConfig'?'current':'next';if(a==='roundConfig'){if(!round()||round().status!=='active')throw new Error('Select an active round.');wizard.rules=structuredClone(round().rules);wizard.roundDate=round().startDate;}else{wizard.rules=structuredClone(l().nextRules||l().rules);const base=new Date(wizard.rules.startDate+'T12:00:00Z');base.setUTCDate(base.getUTCDate()+l().rounds.length*wizard.rules.intervalDays);wizard.roundDate=base.toISOString().slice(0,10);}step=1;drawWizard();return;}
    if(a==='qrPack'){modal('Download all group QRs','The ZIP and six-per-page A4 PDF generator is included in the League Manager server build. It activates on the shared VPS deployment because each QR needs a durable shared result URL.',`<div class="notice"><strong>Server-backed export</strong><br>This browser showcase keeps league edits on this device.</div>`);return;}
    if(a==='groupSchedule'){const r=round();modal('Reschedule this group','Move the remaining unstarted rotations together. Court and player conflicts are checked before saving.',`<form id="group-schedule-form" data-group="${b.dataset.group}" class="stack">${field('Start in league time zone','localDate','','datetime-local','required')}${select('Physical court','court',r.rules.courts.map(c=>[c,c]),r.rules.courts[0])}${button('Reschedule group','saveGroupSchedule','primary','type="submit"')}</form>`);return;}
    if(a==='walkover'){const m=l().rounds.flatMap(r=>r.matches).find(m=>m.id===b.dataset.id);modal('Award an unplayed set','The selected side receives a 6–0 walkover. It counts for league points but is excluded from played-set and win highlights.',`<form id="walkover-form" data-id="${m.id}" class="stack">${select('Winning side','side',m.sides.map((side,i)=>[i,side.map(playerName).join(' / ')]),0)}${field('Reason','reason','','text','required minlength="3"')}${button('Record walkover','saveWalkover','primary','type="submit"')}</form>`);return;}
    if(a==='unbind'){modal('Release court scoring session','The old session will no longer be able to send results. Only completely unscored sessions can be released.',`<form id="unbind-form" data-id="${b.dataset.id}" class="stack">${field('Reason','reason','','text','required minlength="3"')}${button('Release session','saveUnbind','primary','type="submit"')}</form>`);return;}
    if(a==='groupQR'){linkDialog(`${state.publicUrl}/#group/${l().id}/${b.dataset.round}/${b.dataset.group}`,'Group score QR');return;}
    if(a==='resetDemo'){modal('Restart demo','The current run will be archived locally. A fresh first round will be generated.',`${button('Restart and archive current run','doResetDemo','primary')}`);return;}
    if(a==='doResetDemo'){await action('resetDemo');roundId='';close();location.hash='#overview';render();return;}
    if(a==='ratingSeed'||a==='resume'){await action(a);render();return;}
    if(a==='evidence'){await showEvidence(b.dataset.id);return;}
    if(a==='editGroups'||a==='nextGroups'){groupEditor(a==='nextGroups');return;}
    if(a==='toggleEntry'){const e=entry(b.dataset.id);await action('rosterChange',{kind:e.active===false?'restore':'withdraw',id:e.id});render();return;}
    if(a==='editEntry'){const e=entry(b.dataset.id);modal('Edit player names','Player IDs, linked accounts and recorded results stay attached to the same entries.',`<form id="entry-edit-form" data-id="${e.id}" class="stack">${e.players.map((p,i)=>field(`Player ${i+1}`,'name'+i,p.name,'text','required minlength="2"')).join('')}${button('Save names','saveNames','primary','type="submit"')}</form>`);return;}
    if(a==='setRating'){const e=entry(b.dataset.id);modal('Playing level','Self-assessed level is a starting filter. The organizer can edit it and reorder seeds.',`<form id="rating-form" data-id="${e.id}" class="stack">${select('Level','rating',[[1,'1 · New to padel'],[2,'2 · Beginner'],[3,'3 · Improver'],[4,'4 · Intermediate'],[5,'5 · Advanced'],[6,'6 · Competitive'],[7,'7 · Elite']],e.rating||3)}${button('Save level','saveRating','primary','type="submit"')}</form>`);return;}
    if(a==='accountLink'){const account=l().accounts?.find(x=>x.playerId===b.dataset.id);modal('Player account association',`${playerName(b.dataset.id)} · ${account?.email||'No account linked'}`,`<form id="account-form" data-id="${b.dataset.id}" class="stack">${field('Replacement account email (blank to unlink)','email','','email','','The replacement account must already exist. After unlinking, issue a new private invitation from Players.')}${button('Update account association','saveAccount','primary','type="submit"')}</form>`);return;}
    if(a==='correctScore'){const m=l().rounds.flatMap(r=>r.matches).find(m=>m.id===b.dataset.id);modal('Correct official score','Corrections are audited. Closed rounds are protected from accidental retroactive changes.',`<form id="correction-form" data-id="${m.id}" class="stack">${field('Side A games','score0',m.score?.[0]??'','number','required min="0" max="7"')}${field('Side B games','score1',m.score?.[1]??'','number','required min="0" max="7"')}${field('Correction reason','reason','','text','required minlength="3"')}${button('Save correction','saveCorrection','primary','type="submit"')}</form>`);return;}
    if(a==='vision'){const m=l().rounds.flatMap(r=>r.matches).find(m=>m.id===b.dataset.id);modal('Link ROSA Vision match','Link the actual ROSA app match and its available media. Empty links remain unavailable.',`<form id="vision-form" data-id="${m.id}" class="stack">${field('ROSA match ID','rosaMatchId',m.vision?.rosaMatchId||'')}${['summary','replay','livestream','analytics'].map(k=>field(k[0].toUpperCase()+k.slice(1)+' URL',k,m.vision?.links?.[k]||'','url')).join('')}${button('Save match links','saveVision','primary','type="submit"')}</form>`);return;}
    if(a==='pairCourt'){modal('Connect a court monitor','Scan the signed ROSA code on the court monitor, or paste its contents. This associates the court with the league.',`<form id="court-pair-form" class="stack">${select('Court in this league','localCourt',l().rules.courts.map(c=>[c,c]),l().rules.courts[0])}${field('ROSA monitor QR content','code','','text','required placeholder="rosa://court?payload=…"')}${button('Scan with camera','scanCourt','','type="button"')}<video id="scanner" autoplay playsinline hidden></video>${button('Connect verified court','savePair','primary','type="submit"')}</form>`);return;}
    if(a==='scanCourt'){await scanMonitor();return;}

    if(a==='close'){close();return;}if(a==='toggleAuth'){authMode=authMode==='login'?'register':'login';auth();return;}if(a==='logout'){await api('/api/logout',{});await refresh(false);location.hash='#hub';hub();return;}
    if(a==='role'){role=b.dataset.role;location.hash='#overview';render();return;}if(a==='create'||a==='editSettings'){openWizard(a==='editSettings');return;}
    if(a==='demo'){await action('demo',{}, {format:b.dataset.format});render();return;}
    if(a==='wizardBack'){readWizard();step--;drawWizard();return;}if(a==='addSession'){readWizard();wizard.rules.sessions.push({label:'Wednesday evening',day:3,start:'18:00',duration:180,groups:'all',courts:[...wizard.rules.courts]});drawWizard();return;}if(a==='removeSession'){readWizard();wizard.rules.sessions.splice(Number(b.dataset.index),1);drawWizard();return;}
    if(a==='goRoster'){location.hash='#roster';return;}if(a==='goRounds'){location.hash='#rounds';return;}if(a==='group'){groupId=b.dataset.id;location.hash='#rounds';render();return;}
    if(a==='score'){showMatch(b.dataset.id);return;}if(a==='schedule'){showSchedule(b.dataset.id);return;}
    if(a==='start'){await action('start');render();toast('First round published. Court assignments and fixtures are ready.');return;}
    if(['demoNext','demoRound','revokeShares'].includes(a)){await action(a);render();toast(a==='revokeShares'?'Share links revoked.':'Demo results processed. Standings and progression updated.');return;}
    if(a==='add'){modal('Register an entry',l().rules.format==='individual'?'Add one player. Seed determines their initial group.':'A fixed pair stays together throughout the season.',`<form id="add-form" class="stack">${field('Player name','name','','text','required minlength="2"')}${l().rules.format==='pairs'?field('Partner name','partner','','text','required minlength="2"'):''}${button('Add to league','submitAdd','primary','type="submit"')}</form>`);return;}
    if(a==='import'){modal('Import your roster','Use CSV with one player per row, or two columns for fixed pairs. No header row.',`<form id="import-form" class="stack"><div class="field"><label for="csv-file">Choose a CSV file</label><input id="csv-file" type="file" accept=".csv,text/csv"></div><div class="field"><label for="csv-text">Or paste rows</label><textarea id="csv-text" name="rows" placeholder="Alex Moreno${l().rules.format==='pairs'?',Sofia Ramos':''}"></textarea></div>${button('Import entries','submitImport','primary','type="submit"')}</form>`);return;}
    if(a==='seed'){modal('Change initial seed','Entries are grouped in fours in seed order.',`<form id="seed-form" data-id="${b.dataset.id}" class="stack">${field('Seed position','seed',entry(b.dataset.id).seed,'number',`required min="1" max="${l().entrants.length}"`)}${button('Move entry','submitSeed','primary','type="submit"')}</form>`);return;}
    if(a==='remove'||a==='approve'){await action(a,{id:b.dataset.id});render();return;}
    if(a==='confirm'){await action('confirm',{matchId:b.dataset.id,submissionId:b.dataset.submission});close();render();toast('Result confirmed. League progression updated.');return;}
    if(a==='dispute'){modal('Dispute this result','Describe the correction needed. Progression pauses until a corrected result is confirmed.',`<form id="dispute-form" data-id="${b.dataset.id}" class="stack">${field('What needs correcting?','reason','','text','required minlength="3"')}${button('Flag for review','submitDispute','primary','type="submit"')}</form>`);return;}
    if(a==='acceptSchedule'){await action('acceptSchedule',{matchId:b.dataset.id,proposalId:b.dataset.proposal});close();render();toast('Time agreed. Your fixture is updated.');return;}
    if(a==='attendance'){const at=l().rounds.at(-1).attendance[b.dataset.id];modal('Attendance & substitution',playerName(b.dataset.id),`<form id="attendance-form" data-id="${b.dataset.id}" class="stack">${select('Status','status',[['expected','Expected'],['present','Present / checked in'],['absent','Absent']],at.status)}${check('Absence announced in advance','announced',at.announced)}${l().organizer?field('Substitute name (optional)','substitute',at.substitute?.name||'','text','','Assign before any group result is submitted. The substitute fills this slot in every rotation.'):''}${button('Save attendance','submitAttendance','primary','type="submit"')}</form>`);return;}
    if(a==='bind'){modal('Bind ROSA scoring session','Rotating-partner groups bind all three sets to one Core HD league session. Fixed-pair fixtures bind one set. The monitor association supplies the stable ROSA court ID.',`<form id="bind-form" data-id="${b.dataset.id}" class="stack">${select('Physical court','court',l().rules.courts.map(c=>[c,c]),l().rules.courts[0])}${field('Scoring session ID','sessionId','','text','required')}${button('Bind this fixture','submitBind','primary','type="submit"')}</form>`);return;}
    if(a==='invite'){const result=await action('invite',{playerId:b.dataset.id});linkDialog(result.url,'Private player invitation');return;}
    if(['shareRound','matchShare','joinShare'].includes(a)){const result=await action('share',{roundId:round()?.id,matchId:a==='matchShare'?b.dataset.id:undefined,kind:a==='joinShare'?'join':'round'});linkDialog(result.url,a==='joinShare'?'League registration':'Weekly league sharing');return;}
    if(a==='copyLink'){await copy(b.dataset.url);return;}if(a==='copyWeekly'){await copy(weeklyText());return;}if(a==='print'){window.print();return;}if(a==='downloadCards'){await downloadCards();return;}
    if(a==='openSharedMatch'){sessionStorage.setItem('rosa-pending-match',JSON.stringify({leagueId:shared.league.id,matchId:b.dataset.id}));location.hash='#overview';await route();return;}
  }catch(error){const el=$('#form-error');if($('#modal').open&&el)el.textContent=error.message;else toast(error.message);if(error.status===409)await refresh(false);}});
  document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,d=Object.fromEntries(new FormData(f));try{
    if(f.id==='auth-form'){await api(authMode==='login'?'/api/login':'/api/register',d);await refresh(false);if(location.hash==='#login')location.hash=sessionStorage.getItem('rosa-login-return')||'#hub';sessionStorage.removeItem('rosa-login-return');await route();return;}

    if(f.id==='group-schedule-form'){await action('scheduleGroup',{groupId:f.dataset.group,at:localISO(d.localDate,round().rules.timezone),court:d.court});close();render();return;}
    if(f.id==='walkover-form'){await action('walkover',{matchId:f.dataset.id,side:Number(d.side),reason:d.reason});close();render();return;}
    if(f.id==='unbind-form'){await action('unbind',{matchId:f.dataset.id,reason:d.reason});close();render();return;}
    if(f.id==='group-score-form'){const r=l().rounds.find(r=>r.id===f.dataset.round);let count=0;for(const m of [...r.matches]){const a=d[m.id+'-0'],b=d[m.id+'-1'];if(m.status==='official'||a===undefined||b===undefined||a===''||b==='')continue;await action('submit',{matchId:m.id,score:[Number(a),Number(b)],qr:true});count++;}if(!count)throw new Error('Enter both game scores for at least one unfinished set.');await route();toast('Group scores saved.');return;}
    if(f.id==='groups-form'){const values=Object.values(d),groups=Array.from({length:values.length/4},(_,i)=>values.slice(i*4,i*4+4));await action(f.dataset.scope==='next'?'nextGroups':'currentGroups',{groups});roundId='';close();render();return;}
    if(f.id==='entry-edit-form'){await action('rosterChange',{kind:'rename',id:f.dataset.id,names:Object.values(d)});close();render();return;}
    if(f.id==='rating-form'){await action('rating',{id:f.dataset.id,rating:Number(d.rating)});close();render();return;}
    if(f.id==='account-form'){await action('accountLink',{playerId:f.dataset.id,email:d.email});close();render();return;}
    if(f.id==='correction-form'){await action('correct',{matchId:f.dataset.id,score:[Number(d.score0),Number(d.score1)],reason:d.reason});close();render();return;}
    if(f.id==='vision-form'){await action('vision',{matchId:f.dataset.id,...d});close();render();return;}
    if(f.id==='court-pair-form'){await action('pairCourt',d);close();render();return;}

    if(f.id==='wizard-form'){if(wizard.edit&&l().status!=='registration')d.format=l().rules.format;readWizard();if(wizard.edit&&l().status!=='registration')wizard.rules.format=l().rules.format;if(step<3){step++;drawWizard();return;}await action(wizard.scope==='current'?'roundSchedule':wizard.scope==='next'?'nextRules':wizard.edit?'settings':'create',{name:wizard.name,club:wizard.club,rules:wizard.rules,roundId:round()?.id,startDate:wizard.roundDate});close();render();toast('League configuration saved.');return;}
    if(f.id==='add-form')await action('add',{names:l().rules.format==='pairs'?[d.name,d.partner]:[d.name]});
    else if(f.id==='import-form'){const file=$('#csv-file').files[0];if(file&&file.size>250000)throw new Error('CSV must be under 250 KB.');const rows=parseCSV(file?await file.text():d.rows);if(!rows.length)throw new Error('Add at least one row.');await action('import',{rows});}
    else if(f.id==='seed-form')await action('seed',{id:f.dataset.id,seed:Number(d.seed)});
    else if(f.id==='score-form')await action('submit',{matchId:f.dataset.id,score:[Number(d.score0),Number(d.score1)],qr:!!sessionStorage.getItem('rosa-qr-used')});
    else if(f.id==='dispute-form')await action('dispute',{matchId:f.dataset.id,reason:d.reason});
    else if(f.id==='schedule-form')await action('propose',{matchId:f.dataset.id,at:localISO(d.localDate,l().rounds.find(r=>r.matches.some(m=>m.id===f.dataset.id)).rules.timezone),court:d.court});
    else if(f.id==='attendance-form')await action('attendance',{playerId:f.dataset.id,status:d.status,announced:!!d.announced,substitute:d.substitute||''});
    else if(f.id==='bind-form'){const result=await action('bind',{matchId:f.dataset.id,...d});download(new Blob([JSON.stringify(result.binding,null,2)],{type:'application/json'}),'rosa-court-binding.json');}
    else if(f.id==='join-form'){if(!state.user.id){sessionStorage.setItem('rosa-login-return',location.hash);location.hash='#login';return;}await api('/api/join',{token:shared.token,partner:d.partner,rating:Number(d.rating)});await refresh(false);toast('Registration sent to your organizer.');return;}
    else return;
    close();render();toast('Saved. The league is up to date.');
  }catch(error){const el=f.id==='auth-form'?$('#auth-error'):f.id==='group-score-form'?$('#group-error'):$('#form-error');if(el)el.textContent=error.message;else toast(error.message);}});
  document.addEventListener('change',ev=>{const e=ev.target;if(wizard&&step===1&&['f-courtCount','f-scheduling'].includes(e.id)){readWizard();drawWizard();return;}if(e.id==='league-select'){if(e.value==='new'){openWizard();return;}leagueId=e.value;roundId='';groupId='';localStorage.setItem('rosa-league',leagueId);if(!l().organizer)role='player';render();}if(e.id==='round-select'){roundId=e.value;groupId='';render();}if(e.id==='group-select'){groupId=e.value;render();}if(e.id==='share-filter'){shareFilter=e.value;renderShared();}});
  document.addEventListener('input',ev=>{if(ev.target.id==='search'){search=ev.target.value;const start=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);}});
  async function route(){try{
    const hash=location.hash;if(hash.startsWith('#share/')){await showShared(hash.slice(7));return;}
    if(!state){auth();return;}
    if(hash==='#login'){auth();return;}
    if(!state.user.id&&hash.startsWith('#invite/')){auth();return;}
    if(hash.startsWith('#league/')){leagueId=hash.slice(8);location.hash='#overview';return;}
    if(hash.startsWith('#group/')){const bits=hash.split('/');leagueId=bits[1];roundId=bits[2];const r=round(),g=r?.groups.find(g=>g.id===bits[3]);if(!g)throw new Error('This group no longer exists. Open the league to find the new group.');groupPage(r,g);return;}
    if(hash.startsWith('#invite/')){await api('/api/claim',{token:hash.slice(8)});await refresh(false);location.hash='#overview';toast('Player invitation linked to your account.');return;}
    const back=sessionStorage.getItem('rosa-return');if(back){sessionStorage.removeItem('rosa-return');location.hash=back;return;}
    render();const p=sessionStorage.getItem('rosa-pending-match');if(p){const q=JSON.parse(p);if(state.leagues.some(l=>l.id===q.leagueId)){leagueId=q.leagueId;sessionStorage.removeItem('rosa-pending-match');sessionStorage.setItem('rosa-qr-used','1');render();showMatch(q.matchId);}else toast('Use the player invitation from your organizer to link your account first.');}
  }catch(error){$('#app').innerHTML=`<main class="share-page">${brand(true)}${empty('Unable to open this page',error.message,'<a class="btn" href="#overview">Back to league</a>')}</main>`;}}

  let dragEntry=null,scanStream=null;
  document.addEventListener('dragstart',ev=>{const row=ev.target.closest('[data-entry]');if(row?.draggable){dragEntry=row.dataset.entry;ev.dataTransfer.setData('text/plain',dragEntry);ev.dataTransfer.effectAllowed='move';}});
  document.addEventListener('dragover',ev=>{if(dragEntry&&ev.target.closest('[data-entry]'))ev.preventDefault();});
  document.addEventListener('drop',async ev=>{const target=ev.target.closest('[data-entry]');if(!dragEntry||!target)return;ev.preventDefault();const ids=[...l().entrants].sort((a,b)=>a.seed-b.seed).map(e=>e.id),from=ids.indexOf(dragEntry),to=ids.indexOf(target.dataset.entry);dragEntry=null;if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);try{await action('reorder',{ids});render();toast('Seed order updated.');}catch(e){toast(e.message);}});
  document.addEventListener('dragend',()=>dragEntry=null);
  async function scanMonitor(){if(!('BarcodeDetector' in window))throw new Error('Camera QR detection is unavailable in this browser. Paste the monitor QR contents instead.');const video=$('#scanner');scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=scanStream;video.hidden=false;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!$('#modal').open){scanStream?.getTracks().forEach(t=>t.stop());return;}try{const codes=await detector.detect(video);if(codes.length){$('#f-code').value=codes[0].rawValue;scanStream.getTracks().forEach(t=>t.stop());video.hidden=true;return;}}catch{}setTimeout(scan,300);};scan();}
  $('#modal').addEventListener('close',()=>scanStream?.getTracks().forEach(t=>t.stop()));

  window.addEventListener('hashchange',route);
  (async()=>{try{await refresh(false);}catch{state=null;}await route();})();
  setInterval(async()=>{if(!state||$('#modal').open||location.hash.startsWith('#share/')||document.activeElement?.matches('input,textarea,select'))return;try{const before=JSON.stringify(state.leagues.map(l=>[l.id,l.revision]));await refresh(false);if(before!==JSON.stringify(state.leagues.map(l=>[l.id,l.revision])))render();}catch(e){if(e.status===401){state=null;auth();}}},10000);
})();
